"""UI-only V3.1 preview checks. Run with PPAP_PREVIEW_URL against preview Vite.

These checks do not prove real upload, matching, audit, billing or persistence.
The production browser suite remains separate and unchanged.
"""

import os
import re
import time
import unittest
from datetime import datetime, timezone
from urllib.parse import parse_qs, urlencode, urlparse

try:
    from playwright.sync_api import expect, sync_playwright
except ImportError:
    sync_playwright = None

PREVIEW = os.environ.get("PPAP_PREVIEW_URL", "").rstrip("/")


def original_recognition_address(task_url):
    address = urlparse(task_url)
    query = parse_qs(address.query)
    query["recognitionRequest"] = query["task"]
    return address._replace(query=urlencode(query, doseq=True)).geturl()


def evidence_sheet(page):
    return page.get_by_role("dialog", include_hidden=True).filter(has=page.get_by_role("tab", name="核对原件", exact=True, include_hidden=True)).and_(page.locator('[data-state="open"]'))


def close_workspace_panel(page):
    for panel in (
        evidence_sheet(page),
        page.get_by_role("dialog", name="文件信息", exact=True, include_hidden=True),
        page.get_by_role("dialog", name="完成通知设置", exact=True, include_hidden=True),
        page.get_by_role("dialog", name="审核任务", exact=True, include_hidden=True),
        page.get_by_role("dialog", name="历史审核记录", exact=True, include_hidden=True),
    ):
        panel = panel.and_(page.locator('[data-state="open"]'))
        if not panel.is_visible():
            continue
        if panel.get_attribute("aria-hidden") == "true":
            foreground = page.get_by_role("dialog")
            if foreground.count() and foreground.first.get_attribute("data-state") == "open":
                continue
            expect(panel).not_to_have_attribute("aria-hidden", "true")
        panel.get_by_role("button", name="关闭", exact=True, include_hidden=True).click()


def open_basis(page):
    open_task_file(page)
    panel = evidence_sheet(page)
    if not panel.is_visible():
        page.get_by_role("button", name=re.compile("^查看依据 ")).first.click()
    return panel


def select_clause(page, clause):
    close_workspace_panel(page)
    open_task_file(page)
    page.get_by_role("button", name="查看依据 " + clause, exact=True).click()
    return evidence_sheet(page)


def file_information(page):
    open_task_file(page)
    panel = page.get_by_role("dialog", name="文件信息", exact=True, include_hidden=True).and_(page.locator('[data-state="open"]'))
    if not panel.is_visible():
        close_workspace_panel(page)
        page.get_by_role("button", name="文件信息", exact=True).click()
    return panel


def open_task_file(page):
    overview = page.get_by_role("region", name="全部文件概览", exact=True, include_hidden=True)
    details = page.get_by_role("region", name="审核详情", exact=True, include_hidden=True)
    expect(overview.or_(details).first).to_be_visible()
    if overview.is_visible():
        page.get_by_role("navigation", name="文件队列", exact=True).get_by_role("button").first.click()


def audit_details(page):
    open_task_file(page)
    return page.get_by_role("region", name="审核详情", exact=True)


def history_records(page):
    panel = page.get_by_role("dialog", name="历史审核记录", exact=True)
    if not panel.is_visible():
        close_workspace_panel(page)
        page.get_by_role("button", name="历史审核记录", exact=True).click()
    return panel


def select_history(page, sequence):
    panel = history_records(page)
    panel.get_by_role("button", name=f"选择第 {sequence} 次审核", exact=True).click()
    expect(panel).to_have_count(0)


def expect_history_selected(page, sequence):
    expect(page.get_by_role("button", name="历史审核记录", exact=True)).to_contain_text(f"第 {sequence} 次审核")
    panel = history_records(page)
    expect(panel.get_by_role("button", name=f"选择第 {sequence} 次审核", exact=True)).to_have_attribute("aria-pressed", "true")
    close_workspace_panel(page)


def task_list(page):
    listing = page.get_by_role("navigation", name="任务列表", exact=True)
    if not listing.is_visible():
        close_workspace_panel(page)
        page.get_by_role("button", name="打开审核任务", exact=True).click()
    return listing


def new_task(page):
    if not page.get_by_role("button", name="新建审核任务", exact=True).is_visible():
        task_list(page)
    page.get_by_role("button", name="新建审核任务", exact=True).click()


def notification_control(page):
    panel = page.get_by_role("dialog", name="完成通知设置", exact=True, include_hidden=True).and_(page.locator('[data-state="open"]'))
    if not panel.is_visible():
        close_workspace_panel(page)
        page.get_by_role("button", name="完成通知设置", exact=True).click()
    return panel.get_by_role("checkbox", name="完成后飞书通知", exact=True)


def read_results(page):
    basis = evidence_sheet(page)
    clause = basis.get_by_role("heading").first.inner_text().split(" · ", 1)[0] if basis.is_visible() else None
    info = page.get_by_role("dialog", name="文件信息", exact=True, include_hidden=True).is_visible()
    notification = page.get_by_role("dialog", name="完成通知设置", exact=True, include_hidden=True).is_visible()
    close_workspace_panel(page)
    if not page.get_by_role("region", name="比对资料原件", exact=True).is_visible():
        open_task_file(page)
    page.get_by_role("button", name="读取审核结果", exact=True, include_hidden=True).click()
    if clause:
        page.get_by_role("button", name="查看依据 " + clause, exact=True).click()
    elif info:
        file_information(page)
    elif notification:
        page.get_by_role("button", name="完成通知设置", exact=True).click()


def open_reports(page, scene):
    page.goto(PREVIEW + "/preview/audit.html?scene=" + scene)
    page.get_by_role("button", name="使用三类文件示例").click()
    page.get_by_role("button", name="开始识别", exact=True).click()
    page.get_by_role("button", name="开始审核", exact=True).click()
    read_results(page)
    close_workspace_panel(page)
    page.get_by_role("button", name="报告中心", exact=True).click()


def deliver_reply(control):
    """Release a controlled service response, not a user action in the product."""
    control.dispatch_event("click")


@unittest.skipUnless(PREVIEW and sync_playwright, "requires PPAP_PREVIEW_URL and the e2e dependency group (preview-only UI)")
class AuditPreviewTests(unittest.TestCase):
    def test_reference_is_visible_before_confirmation_and_retained_without_a_report(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            page = browser.new_page()
            page.set_default_timeout(5000)
            page.goto(PREVIEW + "/preview/audit.html?scene=with-reference")
            page.get_by_role("button", name="使用三类文件示例").click()
            page.get_by_role("button", name="开始识别", exact=True).click()
            expect(page.get_by_text("3 份文件 · 2 份匹配到规则 · 1 份比对资料", exact=True)).to_be_visible()
            expect(page.get_by_text("预计点数：1000", exact=True)).to_be_visible()
            page.get_by_role("button", name="开始审核", exact=True).click()
            expect(page.get_by_role("heading", name="审核结果", exact=True)).to_be_visible()
            page.get_by_role("navigation", name="文件队列").get_by_role("button", name=re.compile("特殊特性清单.xlsx")).click()
            expect(page.get_by_role("region", name="比对资料原件")).to_be_visible()
            read_results(page)
            expect(page.get_by_text("审核已结束 · 文件已结束 2/2", exact=True)).to_be_visible()
            close_workspace_panel(page)
            page.get_by_role("button", name="报告中心", exact=True).click()
            expect(page.get_by_text("所选报告不可用，请从清单中重新选择。", exact=True)).to_have_count(0)
            expect(page.get_by_role("list", name="逐文件报告清单").get_by_text("特殊特性清单.xlsx", exact=True)).to_have_count(0)
            page.get_by_role("button", name="返回审核结果", exact=True).click()
            expect(page.get_by_role("navigation", name="文件队列").get_by_role("button", name=re.compile("特殊特性清单.xlsx"))).to_be_visible()
            browser.close()

    def test_cancel_cloud_selection_preserves_the_existing_upload_draft_without_importing(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            page = browser.new_page()
            page.set_default_timeout(5000)
            page.goto(PREVIEW + "/preview/audit.html")
            page.get_by_role("button", name="使用三类文件示例", exact=True).click()
            page.get_by_role("checkbox", name="选择 控制计划.xlsx", exact=True).uncheck()
            address = page.url
            page.get_by_role("button", name="从飞书选择", exact=True).click()
            picker = page.get_by_role("dialog", name="从飞书选择文件", exact=True)
            picker.get_by_role("checkbox", name="选择飞书文件 控制计划（飞书文档）", exact=True).check()
            expect(picker.get_by_role("region", name="已选文件", exact=True).get_by_text("控制计划（飞书文档）", exact=True)).to_be_visible()
            picker.get_by_role("button", name="取消", exact=True).click()
            expect(page).to_have_url(address)
            expect(page.get_by_role("checkbox", name="选择 PFMEA.xlsx", exact=True)).to_be_checked()
            expect(page.get_by_role("checkbox", name="选择 控制计划.xlsx", exact=True)).not_to_be_checked()
            expect(page.get_by_role("checkbox", name="选择 过程流程图.pdf", exact=True)).to_be_checked()
            expect(page.get_by_text("控制计划（飞书文档）.docx", exact=True)).to_have_count(0)
            expect(task_list(page).get_by_role("button")).to_have_count(0)
            close_workspace_panel(page)
            browser.close()

    def test_cloud_selection_lists_every_picked_file_and_removal_updates_the_current_folder(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            page = browser.new_page(viewport={"width": 1280, "height": 900})
            page.set_default_timeout(5000)
            page.goto(PREVIEW + "/preview/audit.html?scene=drive-folders")
            page.get_by_role("button", name="从飞书选择", exact=True).click()
            picker = page.get_by_role("dialog", name="从飞书选择文件", exact=True)
            picker.get_by_role("button", name="展开文件夹 客户项目", exact=True).click()
            picker.get_by_role("checkbox", name="选择飞书文件 PFMEA.xlsx", exact=True).check()
            picker.get_by_role("button", name="展开文件夹 补充资料", exact=True).click()
            picker.get_by_role("checkbox", name="选择飞书文件 控制计划.xlsx", exact=True).check()
            selected = picker.get_by_role("region", name="已选文件", exact=True)
            expect(selected.get_by_role("listitem")).to_have_count(2)
            expect(selected.get_by_text("PFMEA.xlsx", exact=True)).to_be_visible()
            expect(selected.get_by_text("控制计划.xlsx", exact=True)).to_be_visible()
            expect(selected.get_by_text("我的云盘 / 客户项目 / 补充资料", exact=True)).to_be_visible()
            expect(picker.get_by_role("button", name="收起文件夹 客户项目", exact=True)).to_have_attribute("aria-expanded", "true")
            expect(picker.get_by_role("button", name="收起文件夹 补充资料", exact=True)).to_have_attribute("aria-expanded", "true")
            selected.get_by_role("button", name="取消选择 控制计划.xlsx", exact=True).click()
            expect(picker.get_by_role("checkbox", name="选择飞书文件 控制计划.xlsx", exact=True)).not_to_be_checked()
            expect(selected.get_by_role("listitem")).to_have_count(1)
            picker.get_by_role("textbox", name="搜索飞书文件名", exact=True).fill("找不到的文件")
            expect(selected.get_by_text("PFMEA.xlsx", exact=True)).to_be_visible()
            picker.get_by_role("button", name="添加 1 份文件", exact=True).click()
            expect(page.get_by_role("heading", name="等待预检查 · 1 份", exact=True)).to_be_visible()
            expect(page.get_by_text("PFMEA.xlsx", exact=True)).to_be_visible()
            expect(page.get_by_text("控制计划.xlsx", exact=True)).to_have_count(0)
            expect(task_list(page).get_by_role("button")).to_have_count(0)
            close_workspace_panel(page)
            browser.close()

    def test_cloud_file_rows_align_and_large_selections_keep_controls_on_screen(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            for width, height in ((1440, 900), (768, 1024), (390, 844)):
                with self.subTest(width=width):
                    page = browser.new_page(viewport={"width": width, "height": height})
                    page.set_default_timeout(5000)
                    page.goto(PREVIEW + "/preview/audit.html?scene=drive-many")
                    page.get_by_role("button", name="从飞书选择", exact=True).click()
                    picker = page.get_by_role("dialog", name="从飞书选择文件", exact=True)
                    current = picker.get_by_role("region", name="云盘文件", exact=True)
                    expect(current.get_by_role("listitem").first).to_contain_text("客户项目")
                    folder = current.get_by_role("button", name="展开文件夹 客户项目", exact=True)
                    first_name = "控制计划-尾门扰流板总成-图纸修订RevC-01.xlsx"
                    row_name = current.get_by_text(first_name, exact=True)
                    picker.evaluate("node => Promise.all(node.getAnimations({subtree: true}).map(animation => animation.finished.catch(() => {})))")
                    bounds = picker.bounding_box()
                    gutter = 15 if width >= 640 else 0
                    self.assertGreaterEqual(bounds["x"], gutter)
                    self.assertLessEqual(bounds["x"] + bounds["width"], width - gutter)
                    if width < 640:
                        self.assertAlmostEqual(bounds["width"], width, delta=1)
                        self.assertAlmostEqual(bounds["height"], height, delta=1)
                    folder_text = folder.get_by_text("客户项目", exact=True).bounding_box()
                    file_text = row_name.bounding_box()
                    self.assertAlmostEqual(folder_text["x"], file_text["x"], delta=1)
                    row_name.click()
                    expect(current.get_by_role("checkbox", name="选择飞书文件 " + first_name, exact=True)).to_be_checked()
                    for index in range(2, 25):
                        if index == 13:
                            current.get_by_role("button", name="加载更多", exact=True).click()
                        current.get_by_role("checkbox", name=f"选择飞书文件 控制计划-尾门扰流板总成-图纸修订RevC-{index:02}.xlsx", exact=True).check()
                    selected = picker.get_by_role("region", name="已选文件", exact=True)
                    expect(selected.get_by_role("listitem")).to_have_count(24)
                    last = selected.get_by_text("控制计划-尾门扰流板总成-图纸修订RevC-24.xlsx", exact=True)
                    last.scroll_into_view_if_needed()
                    for control in (
                        picker.get_by_role("textbox", name="搜索飞书文件名", exact=True),
                        picker.get_by_role("button", name="添加 24 份文件", exact=True),
                        picker.get_by_role("button", name="取消", exact=True),
                    ):
                        rect = control.bounding_box()
                        self.assertGreaterEqual(rect["y"], 0)
                        self.assertLessEqual(rect["y"] + rect["height"], height)
                    expect(picker.get_by_placeholder("筛选已加载文件", exact=True)).to_be_visible()
                    self.assertLessEqual(picker.evaluate("node => node.scrollWidth - node.clientWidth"), 1)
                    self.assertLessEqual(page.evaluate("document.documentElement.scrollWidth"), width)
                    picker.get_by_role("button", name="清空选择", exact=True).click()
                    expect(selected.get_by_role("listitem")).to_have_count(0)
                    expect(current.locator('[role="checkbox"][aria-checked="true"]')).to_have_count(0)
                    expect(picker.get_by_role("button", name="添加 0 份文件", exact=True)).to_be_disabled()
                    picker.get_by_role("button", name="取消", exact=True).click()
                    expect(page.get_by_role("heading", name="上传 PPAP 文件", exact=True)).to_be_visible()
                    expect(task_list(page).get_by_role("button")).to_have_count(0)
                    close_workspace_panel(page)
                    page.close()
            browser.close()

    def test_late_child_folder_read_cannot_replace_the_root_or_import_files(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            page = browser.new_page(viewport={"width": 1280, "height": 900})
            page.set_default_timeout(5000)
            page.goto(PREVIEW + "/__preview?page=audit&scene=drive-folders-late")
            product = page.frame_locator("#product")
            product.get_by_role("button", name="从飞书选择", exact=True).click()
            picker = product.get_by_role("dialog", name="从飞书选择文件", exact=True)
            picker.get_by_role("button", name="展开文件夹 客户项目", exact=True).click()
            expect(picker.get_by_text("正在读取飞书文件…", exact=True)).to_be_visible()
            picker.get_by_role("button", name="收起文件夹 客户项目", exact=True).click()
            expect(picker.get_by_role("button", name="展开文件夹 客户项目", exact=True)).to_be_visible()
            close_workspace_panel(page)
            page.get_by_role("button", name="返回一次示例读取", exact=True).click()
            expect(picker.get_by_role("checkbox", name="选择飞书文件 PFMEA.xlsx", exact=True)).to_have_count(0)
            expect(picker.get_by_role("button", name="添加 0 份文件", exact=True)).to_be_disabled()
            picker.get_by_role("button", name="展开文件夹 客户项目", exact=True).click()
            expect(picker.get_by_role("checkbox", name="选择飞书文件 PFMEA.xlsx", exact=True)).to_be_visible()
            picker.get_by_role("button", name="取消", exact=True).click()
            expect(product.get_by_role("heading", name="上传 PPAP 文件", exact=True)).to_be_visible()
            expect(product.get_by_role("navigation", name="任务列表", exact=True).get_by_role("button")).to_have_count(0)
            browser.close()

    def test_cloud_tree_keeps_siblings_selections_and_per_folder_page_retries_independent(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            page = browser.new_page(viewport={"width": 1440, "height": 900})
            page.set_default_timeout(5000)
            page.goto(PREVIEW + "/preview/audit.html?scene=drive-tree")
            page.get_by_role("button", name="从飞书选择", exact=True).click()
            picker = page.get_by_role("dialog", name="从飞书选择文件", exact=True)
            tree = picker.get_by_role("region", name="云盘文件", exact=True)
            tree.get_by_role("button", name="展开文件夹 客户项目", exact=True).click()
            tree.get_by_role("checkbox", name="选择飞书文件 PFMEA.xlsx", exact=True).check()
            tree.get_by_role("button", name="展开文件夹 共享资料", exact=True).click()
            shared = tree.get_by_role("button", name="收起文件夹 共享资料", exact=True).locator("..")
            expect(shared.get_by_role("checkbox", name="选择飞书文件 PFMEA.xlsx", exact=True)).to_be_checked()
            shared.get_by_role("checkbox", name="选择飞书文件 控制计划.xlsx", exact=True).check()
            selected = picker.get_by_role("region", name="已选文件", exact=True)
            expect(selected.get_by_role("listitem")).to_have_count(2)
            expect(selected.get_by_text("我的云盘 / 客户项目", exact=True)).to_be_visible()
            expect(selected.get_by_text("我的云盘 / 共享资料", exact=True)).to_be_visible()
            ids = tree.get_by_role("checkbox").evaluate_all("nodes => nodes.map(node => node.id)")
            self.assertEqual(len(ids), len(set(ids)))
            tree.get_by_role("button", name="加载更多", exact=True).click()
            expect(tree.get_by_text("飞书文件读取失败，已有文件不会丢失。可以重新读取。", exact=True)).to_be_visible()
            expect(shared.get_by_role("checkbox", name="选择飞书文件 控制计划.xlsx", exact=True)).to_be_checked()
            expect(selected.get_by_role("listitem")).to_have_count(2)
            tree.get_by_role("button", name="重新读取文件", exact=True).click()
            tree.get_by_role("checkbox", name="选择飞书文件 过程流程图.pdf", exact=True).check()
            expect(tree.get_by_role("button", name="收起文件夹 共享资料", exact=True)).to_be_visible()
            expect(selected.get_by_role("listitem")).to_have_count(3)
            selected.get_by_role("button", name="取消选择 PFMEA.xlsx", exact=True).click()
            for checkbox in tree.get_by_role("checkbox", name="选择飞书文件 PFMEA.xlsx", exact=True).all():
                expect(checkbox).not_to_be_checked()
            picker.get_by_role("button", name="取消", exact=True).click()
            expect(task_list(page).get_by_role("button")).to_have_count(0)
            close_workspace_panel(page)
            browser.close()

    def test_cloud_sibling_reads_do_not_block_selection_or_overwrite_other_folders(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            page = browser.new_page(viewport={"width": 1280, "height": 900})
            page.set_default_timeout(5000)
            page.goto(PREVIEW + "/__preview?page=audit&scene=drive-tree-late")
            product = page.frame_locator("#product")
            product.get_by_role("button", name="从飞书选择", exact=True).click()
            picker = product.get_by_role("dialog", name="从飞书选择文件", exact=True)
            tree = picker.get_by_role("region", name="云盘文件", exact=True)
            tree.get_by_role("button", name="展开文件夹 客户项目", exact=True).click()
            expect(tree.get_by_text("正在读取飞书文件…", exact=True)).to_be_visible()
            tree.get_by_role("button", name="展开文件夹 共享资料", exact=True).click()
            tree.get_by_role("checkbox", name="选择飞书文件 控制计划.xlsx", exact=True).check()
            expect(picker.get_by_role("button", name="添加 1 份文件", exact=True)).to_be_enabled()
            close_workspace_panel(page)
            page.get_by_role("button", name="返回一次示例读取", exact=True).click()
