    def test_two_unresolved_display_requests_survive_navigation_and_late_receipts_stay_on_their_files(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            page = browser.new_page(viewport={"width": 1440, "height": 1000})
            page.set_default_timeout(5000)
            page.goto(PREVIEW + "/preview/audit.html?scene=restore-display-loading&task=preview-recovery-task")
            queue = page.get_by_role("navigation", name="文件队列", exact=True)
            dialog = page.get_by_role("dialog", name="更正显示信息", exact=True)
            for index, value in ((0, "文件 A 更正"), (1, "文件 B 更正")):
                close_workspace_panel(page)
                queue.get_by_role("button").nth(index).click()
                file_information(page)
                page.get_by_role("button", name="更正显示信息", exact=True).click()
                dialog.get_by_role("textbox", name="客户", exact=True).fill(value)
                dialog.get_by_role("button", name="保存显示信息", exact=True).click()
                expect(dialog.get_by_role("button", name="正在保存…", exact=True)).to_be_visible()
                dialog.get_by_role("button", name="关闭，稍后核对", exact=True).click()
                close_workspace_panel(page)
                expect(page.get_by_role("complementary", name="预览事件控制", exact=True)).to_be_visible()
            new_task(page)
            page.evaluate("window.postMessage({type:'ppap-preview-read'},location.origin)")
            expect(page.get_by_role("heading", name="上传 PPAP 文件", exact=True)).to_be_visible()
            page.go_back()
            close_workspace_panel(page)
            queue.get_by_role("button").nth(1).click()
            file_information(page)
            page.get_by_role("button", name="更正显示信息", exact=True).click()
            expect(dialog.get_by_role("textbox", name="客户", exact=True)).to_have_value("文件 B 更正")
            expect(dialog.get_by_role("button", name="保存显示信息", exact=True)).to_have_count(0)
            dialog.get_by_role("button", name="核对保存结果", exact=True).click()
            expect(page.get_by_role("region", name="本次审核文件信息", exact=True).get_by_text("文件 B 更正", exact=True)).to_be_visible()
            page.evaluate("window.postMessage({type:'ppap-preview-read'},location.origin)")
            close_workspace_panel(page)
            queue.get_by_role("button").nth(0).click()
            file_information(page)
            page.get_by_role("button", name="更正显示信息", exact=True).click()
            expect(dialog.get_by_role("textbox", name="客户", exact=True)).to_have_value("文件 A 更正")
            dialog.get_by_role("button", name="核对保存结果", exact=True).click()
            expect(page.get_by_role("region", name="本次审核文件信息", exact=True).get_by_text("文件 A 更正", exact=True)).to_be_visible()
            browser.close()

