    def test_display_rejection_unknown_and_conflict_keep_input_and_offer_the_right_recovery(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            for scene in ("rejected", "unknown", "invalid", "conflict"):
                with self.subTest(scene=scene):
                    page = browser.new_page(viewport={"width": 1440, "height": 1000})
                    page.set_default_timeout(5000)
                    page.goto(PREVIEW + f"/preview/audit.html?scene=restore-display-{scene}&task=preview-recovery-task")
                    file_information(page)
                    page.get_by_role("button", name="更正显示信息", exact=True).click()
                    dialog = page.get_by_role("dialog", name="更正显示信息", exact=True)
                    customer = dialog.get_by_role("textbox", name="客户", exact=True)
                    customer.fill("保留此输入")
                    dialog.get_by_role("button", name="保存显示信息", exact=True).click()
                    expect(customer).to_have_value("保留此输入")
                    if scene == "rejected":
                        expect(dialog.get_by_text("保存未执行", exact=True)).to_be_visible()
                        dialog.get_by_role("button", name="保存显示信息", exact=True).click()
                    elif scene == "conflict":
                        expect(dialog.get_by_text("其他操作保存的客户", exact=True)).to_be_visible()
                        expect(dialog.get_by_role("button", name="保存显示信息", exact=True)).to_be_disabled()
                        dialog.get_by_role("button", name="以最新版本继续更正", exact=True).click()
                        expect(customer).to_have_value("保留此输入")
                        dialog.get_by_role("button", name="保存显示信息", exact=True).click()
                    else:
                        expect(dialog.get_by_role("button", name="保存显示信息", exact=True)).to_have_count(0)
                        expect(customer).to_be_disabled()
                        dialog.get_by_role("button", name="关闭，稍后核对", exact=True).click()
                        file_information(page)
                        page.get_by_role("button", name="更正显示信息", exact=True).click()
                        expect(customer).to_have_value("保留此输入")
                        dialog.get_by_role("button", name="核对保存结果", exact=True).click()
                    expect(dialog).not_to_be_visible()
                    expect(page.get_by_role("region", name="本次审核文件信息", exact=True).get_by_text("保留此输入", exact=True)).to_be_visible()
                    page.close()
            browser.close()

