    def test_returned_drafts_read_the_original_upload_request_and_ignore_both_late_receipts(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            page = browser.new_page(viewport={"width": 1440, "height": 1000})
            page.set_default_timeout(5000)
            page.goto(PREVIEW + "/preview/audit.html?scene=upload-loading")
            page.get_by_label("选择审核文件", exact=True).set_input_files({"name": "草稿A.pdf", "mimeType": "application/pdf", "buffer": b"draft-a"})
            expect(page.get_by_role("button", name="返回示例读取 1", exact=True)).to_be_visible()
            new_task(page)
            page.get_by_label("选择审核文件", exact=True).set_input_files({"name": "草稿B.pdf", "mimeType": "application/pdf", "buffer": b"draft-b"})
            expect(page.get_by_role("button", name="返回示例读取 2", exact=True)).to_be_visible()
            page.go_back()
            expect(page.get_by_role("button", name="读取传输 草稿A.pdf", exact=True)).to_be_enabled()
            expect(page.get_by_role("button", name="重试传输 草稿A.pdf", exact=True)).to_be_disabled()
            close_workspace_panel(page)
            page.get_by_role("button", name="返回示例读取 2", exact=True).click()
            close_workspace_panel(page)
            page.get_by_role("button", name="返回示例读取 1", exact=True).click()
            expect(page.get_by_text("草稿B.pdf", exact=True)).to_have_count(0)
            expect(page.get_by_role("heading", name="等待预检查 · 1 份", exact=True)).to_have_count(0)
            expect(page.get_by_role("button", name="读取传输 草稿A.pdf", exact=True)).to_be_enabled()
            page.get_by_role("button", name="读取传输 草稿A.pdf", exact=True).click()
            expect(page.get_by_role("heading", name="等待预检查 · 1 份", exact=True)).to_be_visible()
            expect(page.get_by_text("草稿A.pdf", exact=True)).to_be_visible()
            page.go_forward()
            expect(page.get_by_text("草稿A.pdf", exact=True)).to_have_count(0)
            expect(page.get_by_role("button", name="重试传输 草稿B.pdf", exact=True)).to_be_disabled()
            page.get_by_role("button", name="读取传输 草稿B.pdf", exact=True).click()
            expect(page.get_by_role("heading", name="等待预检查 · 1 份", exact=True)).to_be_visible()
            expect(page.get_by_text("草稿B.pdf", exact=True)).to_be_visible()
            expect(task_list(page).get_by_role("button")).to_have_count(0)
            close_workspace_panel(page)
            browser.close()

