            page.get_by_role("button", name="使用三类文件示例", exact=True).click()
            page.get_by_role("checkbox", name="选择 控制计划.xlsx", exact=True).uncheck()
            page.get_by_label("选择审核文件", exact=True).set_input_files({"name": "草稿A.pdf", "mimeType": "application/pdf", "buffer": b"draft-a"})
            expect(page.get_by_role("heading", name="等待预检查 · 1 份", exact=True)).to_be_visible()
            page.get_by_role("button", name="上一步", exact=True).click()
            new_task(page)
            page.get_by_role("button", name="使用三类文件示例", exact=True).click()
            page.get_by_role("checkbox", name="深度模式", exact=True).check()
            page.get_by_role("button", name="移除 过程流程图.pdf", exact=True).click()
            page.get_by_label("选择审核文件", exact=True).set_input_files({"name": "草稿B.pdf", "mimeType": "application/pdf", "buffer": b"draft-b"})
            expect(page.get_by_role("heading", name="等待预检查 · 1 份", exact=True)).to_be_visible()
            page.get_by_role("navigation", name="产品导航", exact=True).get_by_role("button", name="用量记录", exact=True).click()
            page.go_back()
            expect(page.get_by_text("草稿B.pdf", exact=True)).to_be_visible()
            page.go_back()
            expect(page.get_by_role("heading", name="上传 PPAP 文件", exact=True)).to_be_visible()
            expect(page.get_by_text("已选 3 个文件", exact=True)).to_be_visible()
            expect(page.get_by_text("草稿A.pdf", exact=True)).to_have_count(0)
            expect(page.get_by_text("草稿B.pdf", exact=True)).to_have_count(0)
            page.get_by_role("button", name="查看已选文件", exact=True).click()
            expect(page.get_by_text("草稿A.pdf", exact=True)).to_be_visible()
            expect(page.get_by_role("checkbox", name="选择 控制计划.xlsx", exact=True)).not_to_be_checked()
            expect(page.get_by_role("checkbox", name="选择 过程流程图.pdf", exact=True)).to_be_checked()
            expect(page.get_by_role("checkbox", name="深度模式", exact=True)).not_to_be_checked()
            page.go_forward()
            expect(page.get_by_text("草稿B.pdf", exact=True)).to_be_visible()
            expect(page.get_by_text("草稿A.pdf", exact=True)).to_have_count(0)
            expect(page.get_by_role("checkbox", name="深度模式", exact=True)).to_be_checked()
            expect(page.get_by_role("heading", name="已移除文件", exact=True)).to_have_count(0)
            expect(page.get_by_role("checkbox", name="选择 过程流程图.pdf", exact=True)).to_have_count(0)
            # Usage also reads fourteen historical source tasks; neither upload draft creates one.
            expect(task_list(page).get_by_role("button")).to_have_count(15)
            close_workspace_panel(page)
            browser.close()

