            page.goto(PREVIEW + "/preview/audit.html?scene=reports-share-partial-retry-not-accepted&task=preview-report-task&report=1")
            page.get_by_role("button", name="分享", exact=True).click()
            dialog = page.get_by_role("dialog", name="分享审核报告", exact=True)
            dialog.get_by_role("checkbox", name="选择人员 示例李工", exact=True).check()
            dialog.get_by_role("checkbox", name="选择人员 示例王工", exact=True).check()
            dialog.get_by_role("button", name="发送给 2 个目标", exact=True).click()
            dialog.get_by_role("button", name="读取发送结果", exact=True).click()
            wang = dialog.get_by_role("listitem", name="发送到 示例王工", exact=True)
            wang.get_by_role("button", name="仅重试 示例王工", exact=True).click()
            expect(wang.get_by_text("结果未知", exact=True)).to_be_visible()
