    def test_share_directory_failure_and_empty_results_never_enable_send(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            for scene in ("reports-share-directory-error", "reports-share-directory-empty", "reports-share-directory-denied"):
                with self.subTest(scene=scene):
                    page = browser.new_page()
                    page.set_default_timeout(5000)
                    page.goto(PREVIEW + "/preview/audit.html?scene=" + scene + "&task=preview-report-task&report=1")
                    page.get_by_role("button", name="分享", exact=True).click()
                    dialog = page.get_by_role("dialog", name="分享审核报告", exact=True)
                    if scene.endswith("empty"):
                        expect(dialog.get_by_text("没有符合条件的组织内目标。", exact=True)).to_be_visible()
                    else:
                        expect(dialog.get_by_text("目录暂不可用", exact=True)).to_be_visible()
                    expect(dialog.get_by_role("button", name="发送给 0 个目标", exact=True)).to_be_disabled()
                    if scene.endswith("error"):
                        dialog.get_by_role("button", name="重新读取目标", exact=True).click()
                        expect(dialog.get_by_role("checkbox", name="选择人员 示例李工", exact=True)).to_be_visible()
                    page.close()
            browser.close()

