    def test_an_observed_pending_share_takes_priority_over_an_unsent_draft_until_reconciled(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            page = browser.new_page(viewport={"width": 1440, "height": 1000}, permissions=["clipboard-read", "clipboard-write"])
            page.set_default_timeout(5000)
            open_reports(page, "reports-share-external")
            page.get_by_role("button", name="分享", exact=True).click()
            dialog = page.get_by_role("dialog", name="分享审核报告", exact=True)
            dialog.get_by_role("checkbox", name="选择人员 示例王工", exact=True).check()
            dialog.get_by_role("tab", name="文件", exact=True).click()
            dialog.get_by_role("button", name="关闭", exact=True).click()
            page.get_by_role("button", name="读取报告状态", exact=True).click()
            page.get_by_role("button", name="分享", exact=True).click()
            delivery = dialog.get_by_role("listitem", name="发送到 示例李工", exact=True)
            expect(delivery).to_contain_text("结果未知")
            expect(dialog.get_by_role("button", name=re.compile("^发送给"))).to_have_count(0)
            expect(dialog.get_by_role("button", name="新的分享", exact=True)).to_have_count(0)
            dialog.get_by_role("button", name="联系支持", exact=True).click()
            support = page.get_by_role("dialog", name="联系我们", exact=True)
            support.get_by_role("button", name="复制操作信息", exact=True).click()
            copied = page.evaluate("navigator.clipboard.readText()")
            for value in ("原请求：preview-external-share", "交付方式：链接", "示例李工", "PFMEA.xlsx-审核报告"):
                self.assertIn(value, copied)
            self.assertNotIn("示例王工", copied)
            page.keyboard.press("Escape")
            dialog.get_by_role("button", name="读取发送结果", exact=True).click()
            expect(delivery).to_contain_text("结果未知")
            dialog.get_by_role("button", name="读取发送结果", exact=True).click()
            expect(delivery).to_contain_text("已发送")
            expect(dialog.get_by_role("button", name="新的分享", exact=True)).to_be_visible()
            expect(dialog.get_by_role("tab", name="文件", exact=True)).to_have_count(0)
            browser.close()

