    def test_unknown_acceptance_reads_the_same_receipt_without_a_second_command(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            page = browser.new_page(viewport={"width": 1440, "height": 1000}, permissions=["clipboard-read", "clipboard-write"])
            page.set_default_timeout(5000)
            page.goto(PREVIEW + "/preview/audit.html?scene=confirm-unknown")
            page.get_by_role("button", name="使用三类文件示例").click()
            page.get_by_role("button", name="开始识别", exact=True).click()
            page.get_by_role("button", name="开始审核", exact=True).click()
            expect(page.get_by_text("受理结果待核对", exact=True)).to_be_visible()
            request = page.get_by_role("alert").get_attribute("data-request-id")
            expect(page.get_by_role("button", name="开始审核", exact=True)).to_be_disabled()
            expect(page.get_by_role("button", name="上一步", exact=True)).to_be_disabled()
            support_trigger = page.get_by_role("button", name="联系支持", exact=True)
            support_trigger.click()
            support = page.get_by_role("dialog", name="联系我们", exact=True)
            support.get_by_role("button", name="复制操作信息", exact=True).click()
            copied = page.evaluate("navigator.clipboard.readText()")
            self.assertIn("确认审核", copied)
            self.assertIn(request, copied)
            self.assertIn(parse_qs(urlparse(page.url).query)["task"][0], copied)
            self.assertIn("未取得受理回执。审核可能已经开始", copied)
            self.assertNotIn("服务请求编号", copied)
            page.keyboard.press("Escape")
            expect(support_trigger).to_be_focused()
            expect(page.get_by_role("alert")).to_have_attribute("data-request-id", request)
            expect(page.get_by_role("button", name="开始审核", exact=True)).to_be_disabled()
            page.get_by_role("button", name="读取受理结果", exact=True).click()
            expect(page.get_by_role("alert")).to_have_attribute("data-request-id", request)
            expect(page.get_by_role("button", name="开始审核", exact=True)).to_be_disabled()
            page.get_by_role("button", name="读取受理结果", exact=True).click()
            expect(page.get_by_role("heading", name="审核结果", exact=True)).to_be_visible()
            expect(task_list(page).get_by_role("button")).to_have_count(1)
            close_workspace_panel(page)
            browser.close()

    def test_support_preserves_the_failed_confirmation_trace_while_its_original_receipt_arrives(self):
        with sync_playwright() as playwright:
            browser = playwright.chromium.launch()
            page = browser.new_page(viewport={"width": 1440, "height": 1000}, permissions=["clipboard-read", "clipboard-write"])
            page.set_default_timeout(5000)
            page.add_init_script("""if (navigator.clipboard) {
                const write = navigator.clipboard.writeText.bind(navigator.clipboard);
                navigator.clipboard.writeText = async value => {
                    await new Promise(resolve => setTimeout(resolve, 250));
                    return write(value);
                };
            }""")
            page.goto(PREVIEW + "/__preview?page=audit&scene=confirm-traced")
            preview = page.frame_locator("iframe")
            preview.get_by_role("button", name="使用三类文件示例", exact=True).click()
            preview.get_by_role("button", name="开始识别", exact=True).click()
            preview.get_by_role("button", name="开始审核", exact=True).click()
            notice = preview.get_by_role("alert").filter(has_text="受理结果待核对")
            expect(notice).to_be_visible()
            request_id = notice.get_attribute("data-request-id")
            preview.get_by_role("button", name="读取受理结果", exact=True).click()
            preview.get_by_role("button", name="联系支持", exact=True).click()
            support = preview.get_by_role("dialog", name="联系我们", exact=True)
            expect(support.get_by_label("服务请求编号", exact=True)).to_have_value("preview-confirm-service-170")
            expect(support.get_by_label("页面参考编号", exact=True)).to_have_value(re.compile(r"^client-"))
            support.get_by_role("button", name="复制操作信息", exact=True).click()
            expect(support.get_by_text("已复制。", exact=True)).to_be_visible()
            before = page.evaluate("navigator.clipboard.readText()")
            self.assertIn(request_id, before)
            self.assertIn("服务请求编号：preview-confirm-service-170", before)
            close_workspace_panel(page)
            page.get_by_role("button", name="返回一次示例读取", exact=True).click()
            page.evaluate("navigator.clipboard.writeText('not-the-operation')")
            support.get_by_role("button", name="复制操作信息", exact=True).click()
            deadline = time.monotonic() + 5
            while page.evaluate("navigator.clipboard.readText()") != before and time.monotonic() < deadline:
                page.wait_for_timeout(20)
            self.assertEqual(page.evaluate("navigator.clipboard.readText()"), before)
            support.get_by_role("button", name="关闭", exact=True).click()
            expect(preview.get_by_role("heading", name="审核结果", exact=True)).to_be_visible()
            task_list(preview)
            expect(preview.get_by_role("navigation", name="任务列表", exact=True).get_by_role("button")).to_have_count(1)
            close_workspace_panel(preview)
            preview.get_by_role("button", name="联系我们", exact=True).click()
            expect(support.get_by_label("服务请求编号", exact=True)).to_have_count(0)
            support.get_by_role("button", name="复制场景与编号", exact=True).click()
            expect(support.get_by_text("已复制。", exact=True)).to_be_visible()
            self.assertNotIn("preview-confirm-service-170", page.evaluate("navigator.clipboard.readText()"))
            browser.close()

